import base64
import hashlib
import io
import json
from pathlib import Path

from evidencedoc.documents import read_document, render_page

root = Path(__file__).resolve().parents[1]
rows = json.loads((root / "evaluation/results/cpu-probe.json").read_text())["results"]
document = read_document(root / "examples/technical-catalog.pdf")
assets = {}
cases = {}
for row in rows:
    report = row["report"]
    evidence = report["evidence"]
    page = evidence[0]["page"] if evidence else report["retrieved_pages"][0]["page"]
    quote = evidence[0]["quote"] if evidence else ""
    image = render_page(document, page, quote)
    image.thumbnail((840, 1188))
    buffer = io.BytesIO()
    image.save(buffer, format="WEBP", quality=82)
    payload = buffer.getvalue()
    key = hashlib.sha256(payload).hexdigest()[:12]
    assets[key] = "data:image/webp;base64," + base64.b64encode(payload).decode()
    case = cases.setdefault(row["id"], {"question": report["question"], "modes": {}})
    case["modes"][row["mode"]] = {"report": report, "image": key, "preview_page": page}
fixture = json.loads((root / "examples/technical-catalog.fixture.json").read_text())
content = json.dumps(
    {"cases": cases, "assets": assets, "sample": fixture}, ensure_ascii=False
).replace("<", "\\u003c")
